def transform(grid):
    out = [row[:] for row in grid]
    w = len(grid[0])
    full_row_colors = {row[0] for row in grid if all(v == row[0] for v in row)}

    for r, row in enumerate(grid):
        first = row[0]
        if first not in full_row_colors:
            continue
        k = 1
        while k < w and row[k] == first:
            k += 1
        if 0 < k < w and all(v != first for v in row[k:]):
            for c in range(k, w):
                out[r][c] = 1

    return out
